{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Tirabrutinib, a near-identical analogue sharing the pyrrolopyrimidinone core, diaryl ether, and lactam amide, was directly measured in rats with an unbound brain-to-plasma ratio of 8.5% and classified as BBB-permeable, providing strong transferable evidence for meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A closely related acrylamide-containing analogue achieved a Kp,uu of 0.37 in a rat constant-infusion study and was classified as permeable, showing that this scaffold can sustain adequate unbound brain exposure despite moderate physicochemical constraints.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A structurally related heteroaromatic amide showed a rat brain/plasma ratio of 1.66 and was classified as having good CNS penetration, supporting the ability of similar molecules to cross the BBB in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In humans, a related piperidine/heteroaromatic compound had CSF concentrations at least equal to free plasma concentrations, demonstrating that this chemical class can achieve meaningful CNS exposure in the most translationally relevant species.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer direct in vivo measurements in rats, monkeys, and humans show that close structural analogues of the query achieve meaningful CNS exposure; the near-identical tirabrutinib analogue is classified BBB-permeable with measurable unbound brain concentrations.",
  "evidence_gaps": [
    "No exact-query Kp,uu or CSF measurement is available; the decision relies on very close analogues.",
    "Efflux transporter substrate status for the exact query is not directly quantified, though the analogue evidence suggests adequate net brain exposure.",
    "The acrylamide warhead may alter plasma pharmacokinetics, but this does not negate the demonstrated CNS access of the chemotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

